export const symbols = {
 Home:svg('<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>'),
 Events:svg('<circle cx="12" cy="12" r="9"/><path d="M12 7v5h4"/>'),
 Services:svg('<path d="m12 3 9 4v6c0 5-9 9-9 9S3 18 3 13V7z"/><path d="m8 12 3 3 5-6"/>'),
 Smart:svg('<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3z"/><circle cx="12" cy="12" r="3"/>'),
 Shop:svg('<path d="M5 6h14l2 15H3zM8 6V4a4 4 0 0 1 8 0v2M8 11q4 5 8 0"/>'),
 menu:svg('<path d="M4 6h16M4 12h16M4 18h16"/>'),
 plus:svg('<circle cx="12" cy="12" r="9"/><path d="M7 12h10M12 7v10"/>'),
 history:svg('<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2"/>'),
 settings:svg('<circle cx="12" cy="12" r="4"/><path d="m9 3 1-1h4l1 3 3 1 3 1v4l-2 2-1 3v3l-4 2-3-2-3-1H5l-2-4 2-3 1-3V5z"/>')
};
const tabs=['Home','Events','Services','Smart','Shop'];
const nav = active => tabs.map(name=>`<a href="#${name.toLowerCase()}" class="shell-link ${name.toLowerCase()===active?'active':''}" ${name.toLowerCase()===active?'aria-current="page"':''}>${symbols[name]}<span>${name}</span></a>`).join('');
export function setupShell(){
 document.querySelector('#app').insertAdjacentHTML('beforebegin',`<header class="shell-header"><a class="wordmark" href="#home" aria-label="eufy prototype home">eufy<span>Security</span></a><button class="shell-icon" id="menu-toggle" aria-label="Open menu" aria-expanded="false">${symbols.menu}</button><a class="house-name" href="#home">yenyong929's Home <span>⌄</span></a><span class="prototype-tag">Interactive prototype</span><button class="shell-icon" id="messages-open" aria-label="Messages">${svg('<path d="M3 4h18v13H9l-5 4v-4H3zM7 10h.1M12 10h.1M17 10h.1"/>')}</button><button class="shell-icon" id="add-toggle" aria-label="Add menu" aria-expanded="false">${symbols.plus}</button></header><aside class="desktop-nav" aria-label="Main navigation"></aside><div id="drawer-backdrop" hidden></div><aside id="drawer" aria-label="Account menu" hidden><button id="close-drawer" class="shell-icon close-drawer" aria-label="Close menu">✕</button><div class="account"><span class="account-avatar">Y</span><strong>yenyong929</strong></div><div class="drawer-group">${['Cloud Backup','Services'].map(x=>`<button data-original="${x}">${symbols.Services}${x}</button>`).join('')}</div><div class="drawer-group">${['Third Party Services','Widget','Customize Homepage','Share Devices'].map(x=>`<button data-original="${x}">${symbols.Smart}${x}${x==='Widget'?'<small>New</small>':''}</button>`).join('')}<button data-original="Settings">${symbols.settings}Settings</button></div><div class="drawer-group"><button data-original="Pro Security">${symbols.Services}Pro Security</button></div></aside>`);
 document.querySelector('#app').insertAdjacentHTML('afterend','<div id="add-popover" hidden><button data-original="Add Device">Add Device</button><button data-original="Add Favorites">Add Favorites</button><button data-original="Scan QR Code">Scan QR Code</button></div><nav class="mobile-nav" aria-label="Main navigation"></nav><dialog id="native-dialog"><h2 id="native-title"></h2><p>This existing eufy feature is shown for context in this prototype.</p><form method="dialog"><button class="eufy-primary">Close</button></form></dialog>');
 const toggle=open=>{document.querySelector('#drawer').hidden=!open;document.querySelector('#drawer-backdrop').hidden=!open;document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open));if(open)document.querySelector('#close-drawer').focus();else document.querySelector('#menu-toggle').focus();};
 document.querySelector('#menu-toggle').onclick=()=>toggle(true);
 document.querySelector('#messages-open').onclick=()=>{location.hash='messages';};
 const add=document.querySelector('#add-popover');
 document.querySelector('#add-toggle').onclick=()=>{add.hidden=!add.hidden;document.querySelector('#add-toggle').setAttribute('aria-expanded',String(!add.hidden));};
 document.addEventListener('click',e=>{if(!e.target.closest('#add-popover, #add-toggle')){add.hidden=true;document.querySelector('#add-toggle').setAttribute('aria-expanded','false');}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){add.hidden=true;document.querySelector('#add-toggle').setAttribute('aria-expanded','false');}});
 document.querySelector('#close-drawer').onclick=()=>toggle(false);
 document.querySelector('#drawer-backdrop').onclick=()=>toggle(false);
 document.querySelector('#drawer').addEventListener('click',e=>{if(e.target.closest('a'))toggle(false);});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#drawer').hidden)toggle(false);});
 document.addEventListener('click',e=>{const button=e.target.closest('[data-original]');if(button){if(button.dataset.original==='Services'){toggle(false);location.hash='services';return;}add.hidden=true;document.querySelector('#add-toggle').setAttribute('aria-expanded','false');document.querySelector('#native-title').textContent=button.dataset.original;document.querySelector('#native-dialog').showModal();}});
}
export function updateShell(route){
 const active=(route.startsWith('history')||route.startsWith('events'))?'events':(tabs.map(x=>x.toLowerCase()).includes(route)?route:'home');
 document.querySelector('.mobile-nav').innerHTML=nav(active);
 document.querySelector('.desktop-nav').innerHTML=`<nav>${nav(active)}</nav><div class="nav-divider"></div><p class="sidebar-note">eufy interface reference<br>Access History in Events</p>`;
 document.body.dataset.route=route;
 document.body.dataset.page=(route.startsWith('history')||route.startsWith('events/access'))?'history':active;
}
