const entrance=`<svg viewBox="0 0 500 260" aria-hidden="true"><path d="M0 0h500v205H0z" fill="#eaf2fd"/><path d="M0 205h500v55H0z" fill="#d6e4f5"/><path d="M0 205h500" stroke="#bfcee3" stroke-width="3"/><rect x="184" y="20" width="132" height="187" rx="3" fill="#b8cde6"/><rect x="191" y="26" width="118" height="180" fill="#f3f7fc"/><rect x="203" y="40" width="94" height="70" rx="2" fill="#e2ecf8" stroke="#d0deed"/><rect x="203" y="122" width="94" height="68" rx="2" fill="#e2ecf8" stroke="#d0deed"/><path d="M287 112h-10" stroke="#819db9" stroke-width="4" stroke-linecap="round"/><circle cx="250" cy="32" r="2" fill="#7a96b2"/><path d="m167 224 20-17h128l20 17z" fill="#aabfd9"/><path d="M58 126h76v8H58zm5 8v72m65-72v72" stroke="#b7cae3" stroke-width="4"/><rect x="73" y="92" width="33" height="33" rx="4" fill="#f8fbff"/><path d="M90 98v23m-9-11 9 7 9-7" stroke="#b9cfdf" stroke-width="3" fill="none"/><path d="M384 159v-57" stroke="#99b7c7" stroke-width="5"/><ellipse cx="372" cy="110" rx="10" ry="23" transform="rotate(-35 372 110)" fill="#b8cddc"/><ellipse cx="396" cy="130" rx="10" ry="23" transform="rotate(35 396 130)" fill="#a9c4d5"/><path d="M365 157h38l-5 48h-28z" fill="#c0d2e6"/><rect x="87" y="39" width="42" height="42" fill="#fff"/><rect x="91" y="43" width="34" height="34" fill="#d6e5f5"/></svg>`;
const deviceArtwork=id=>id==='front-door'?entrance:room;
const devices=[{id:'living-room',name:'Living Room',model:'Indoor Cam E30',person:'emma',member:'Emma'},{id:'front-door',name:'Front Door',model:'Indoor Cam',person:'james',member:'James'}];
const cameraProduct=`<svg viewBox="0 0 80 100" role="img" aria-label="White indoor security camera"><defs><linearGradient id="cam-white" x2="1" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#dce6ee"/></linearGradient></defs><ellipse cx="40" cy="91" rx="25" ry="5" fill="#d8e5ef"/><rect x="33" y="65" width="14" height="20" rx="6" fill="#d3e0eb"/><ellipse cx="40" cy="84" rx="23" ry="7" fill="#f7fbfe" stroke="#d7e4ee"/><rect x="13" y="7" width="54" height="66" rx="25" fill="url(#cam-white)" stroke="#d8e4ed"/><rect x="20" y="14" width="40" height="41" rx="19" fill="#132634"/><circle cx="40" cy="34" r="12" fill="#2d4e64"/><circle cx="40" cy="34" r="7" fill="#0b1726"/><circle cx="43" cy="31" r="3" fill="#6bafd3"/><circle cx="40" cy="60" r="2" fill="#00bed8"/></svg>`;
let eventDay=21;
let rangeStart="00:00",rangeEnd="23:59";
export const getEventRange=()=>[rangeStart,rangeEnd];
