export function nativeView(page,app){
 app.className=`native-page native-${page}`;
 document.title=`eufy · ${page[0].toUpperCase()+page.slice(1)}`;
 if(page==='home')app.innerHTML=`<div class="devices-heading"><div><h1>My Devices</h1><p>2 indoor cameras · 1 robot vacuum</p></div><button class="eufy-primary" data-original="Add Device">Add Device</button></div><div class="device-grid">${devices.map(device=>`<article class="device-card"><div class="device-card-heading"><div><h2>${device.name}</h2><p>${device.model} <span>· Demo device</span></p></div><div class="camera-product">${device.id==='living-room'?`<img src="${catalog[0].image}" alt="Indoor Cam E30">`:cameraProduct}</div></div><a href="#device/${device.id}" class="device-preview" aria-label="Open ${device.name} camera"><div class="device-room">${deviceArtwork(device.id)}</div><span class="demo-view">Illustrated preview</span><span class="play-button" aria-hidden="true">▶</span><span class="device-location">${device.name}</span></a><div class="device-actions"><a href="#device/${device.id}">${symbols.Home}<span>View Camera</span></a><a href="#events/access">${symbols.Events}<span>Access History</span></a><a href="#events/permissions/${device.person}">${symbols.Services}<span>Permissions</span></a></div></article>`).join('')}${vacuumCard()}</div>`;
 else if(page.startsWith('device/')){
 const device=devices.find(d=>d.id===page.split('/')[1])||devices[0];
 document.title=`eufy · ${device.name} Camera`;
 app.innerHTML=`<div class="page-heading"><a href="#home" aria-label="Back to Home">‹</a><h1>${device.name}</h1><span class="badge">${device.model}</span></div><section class="camera-detail"><div class="device-preview detail-preview"><div class="device-room">${deviceArtwork(device.id)}</div><span class="demo-view">Demo live view</span><span class="device-location">${device.name} · Indoor</span></div><p class="camera-demo-note">Illustration only · This prototype is not connected to a real camera.</p><div class="camera-detail-actions"><a class="eufy-primary" href="#events/access">Access History</a><a class="eufy-secondary" href="#events/permissions/${device.person}">Viewing Permissions</a></div><div class="camera-access-info"><strong>${device.member}'s viewing permissions</strong><p>Review who can access this camera and choose what they can see.</p></div></section>`;
 }
 else if(page==='events'){
 app.innerHTML=eventsHeader('events')+`<div class="native-empty event-empty"><div class="empty-document">${svg('<path d="M6 3h10l3 3v15H6zM9 8h5m-5 4h5m-5 4h3"/><circle cx="17" cy="16" r="4"/><path d="m20 19 3 3"/>')}</div><h1>No event this day</h1></div>`;
 bindEventsCalendar(()=>nativeView(page,app));
 }else if(page==='messages'){
 app.innerHTML=`<div class="message-layout"><div class="page-heading"><a href="#home" aria-label="Back to Home">‹</a><h1>Messages</h1><button class="shell-icon" data-original="Clear messages" aria-label="Clear messages">${svg('<path d="m12 3-2 10m-6 7 3-10 10 2 2 8zM6 17h12"/>')}</button><a class="shell-icon" href="#notifications" aria-label="Notification settings">${symbols.settings}</a></div><div class="message-tabs" role="tablist" aria-label="Message categories"><button role="tab" aria-selected="false" id="message-top">Top <span style="color:#ff5353">•</span></button><button role="tab" aria-selected="true" id="message-information">Information</button></div><div id="message-panel" role="tabpanel"><div class="message-list">${[[svg('<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4"/>'),'System Messages'],[svg('<path d="M3 4h18v14H9l-5 3v-3H3zM8 14v-4h8m-3-3 3 3-3 3"/>'),'Sharing Messages'],[svg('<path d="M4 14V11a8 8 0 0 1 16 0v6q0 4-7 4M2 11h4v7H2zM18 11h4v7h-4z"/>'),'Service Messages'],[svg('<circle cx="9" cy="8" r="3"/><circle cx="17" cy="10" r="2"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 15q5 0 5 6"/>'),'Community Messages']].map(([i,x])=>`<button data-original="${x}"><span class="message-icon">${i}</span>${x}</button>`).join('')}</div><h2 class="device-messages">Device Messages</h2><div class="no-messages"><span aria-hidden="true">▱</span>No messages</div></div></div>`;
 const info=document.querySelector('#message-information'),top=document.querySelector('#message-top'),panel=document.querySelector('#message-panel');const content=panel.innerHTML;
 top.onclick=()=>{top.setAttribute('aria-selected','true');info.setAttribute('aria-selected','false');panel.innerHTML='<div class="no-messages"><span aria-hidden="true">▱</span>No messages</div>';};info.onclick=()=>{info.setAttribute('aria-selected','true');top.setAttribute('aria-selected','false');panel.innerHTML=content;};
 }else if(page==='notifications'){
 app.innerHTML=`<div class="message-layout"><div class="page-heading"><a href="#messages" aria-label="Back to Messages">‹</a><h1>Notifications</h1></div><div class="settings-group"><button class="setting-row" data-original="Allow Notifications"><span>Allow Notifications</span><span class="setting-value">On</span><span>›</span></button></div><div class="settings-group"><button class="setting-row" data-original="Email notifications"><span>Email</span><span class="setting-value">Off</span><span>›</span></button><button class="setting-row" data-original="APP Notification"><span>APP Notification</span><span class="setting-value">Off</span><span>›</span></button></div><p class="notification-copy">Subscribe exclusive offers, news, discounts, and product updates from Anker or eufy through email and app notification.</p></div>`;
 }else if(page==='services')app.innerHTML=`<div class="native-tabs"><strong>Insights</strong><button data-original="Services">Services</button></div><h1>Space Status</h1><p class="space-status"><span>●</span> 0 Space &nbsp; | &nbsp; 3 Devices &nbsp; | &nbsp; 0 Service Active</p><div class="service-grid"><article class="native-service-card"><div class="room-art">${room}</div><h2>Add Space</h2><p>Set up a new room</p><button class="eufy-dark" data-original="Add Space">Add Space</button></article><section><h2>Device Health</h2><article class="native-service-card"><div class="room-art">${room}</div><button class="eufy-dark" data-original="Add Device">Add Device</button></article></section></div>`;
 else if(page==='smart')app.innerHTML=`<div class="native-tabs"><strong>Modes</strong><button data-original="Automation">Automation</button></div><div class="native-empty"><div class="room-art">${room}</div><h1>Add Security Devices to Control Your Home<br>with Modes</h1><button class="eufy-primary" data-original="Add Device">Add Device</button></div>`;
 else app.innerHTML=`${productCards()}<div class="shop-search"><input aria-label="Search products" placeholder="Robot Vacuums Omni S1 Pro"><button data-original="Account" aria-label="Shop account">♙</button><button data-original="Cart" aria-label="Cart">${symbols.Shop}</button></div><section class="shop-hero"><div><p>Video Doorbell E340</p><h1>Dual Cameras Protect<br>Your Door and Deliveries</h1><button data-original="Upgrade for Less">Upgrade for Less</button><p class="shop-coupon">Up to <strong>$239 Off</strong></p><div class="shop-awards">Subscription <strong>Free</strong><span>expertreviews<br>VIDEO DOORBELL OF THE YEAR<br>2025</span></div></div><div class="door-art"><div class="door-panels"></div><div class="doorbell"><i></i><span>eufy</span><b></b></div><div class="parcel"></div></div></section><div class="shop-shortcuts">${['Upgrade','Referral','Pan-Tilt-Zoom Cam'].map((x,i)=>`<button data-original="${x}"><span>${['↻','♡','▣'][i]}</span>${x}</button>`).join('')}</div><section class="shop-offer"><h2>Buy Robot Lawn Mower</h2><p>Get a FREE X10 Pro Omni</p><button class="eufy-primary" data-original="Buy Now">Buy Now</button><div class="shop-products">${[['New Homebase','Up to $300 OFF'],['Dual Cameras...','Save up to $239 off'],['Bottle Washer','10% Off.App Only']].map(([x,y])=>`<button data-original="${x}"><strong>${x}</strong><small>${y}</small><span>▥</span></button>`).join('')}</div></section>`;
}

export function eventsHeader(active='events'){return `${eventTabs(active)}<div class="event-toolbar"><button class="round-button" id="previous-day" aria-label="Previous day">‹</button><button class="event-date" id="calendar-open">Oct ${eventDay}<small>2026</small></button><button class="round-button" id="next-day" aria-label="Next day" ${eventDay===31?'disabled':''}>›</button><span class="toolbar-spacer"></span><button class="shell-icon" data-original="Event filters" aria-label="Filter events">${svg('<path d="M3 4h18l-7 8v8l-4-2v-6z"/>')}</button><button class="shell-icon" id="calendar-button" aria-label="Open calendar">${svg('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v5m10-5v5M3 10h18"/>')}</button></div><dialog id="calendar-dialog"><div class="calendar-month"><span>Sep</span><h2>Oct 2026</h2><span>Nov</span></div><div class="calendar-grid">${'<span></span>'.repeat(4)}${Array.from({length:31},(_,i)=>`<button data-calendar-day="${i+1}" aria-pressed="${i+1===eventDay}" class="${i+1===eventDay?'selected':''}">${i+1}</button>`).join('')}</div><p>Time Range</p><div class="time-inputs"><label>From <input id="range-start" type="time" value="${rangeStart}" required></label><label>To <input id="range-end" type="time" value="${rangeEnd}" required></label></div><div class="calendar-actions"><button id="calendar-today" class="eufy-secondary">Back to today</button><button id="calendar-confirm" class="eufy-primary">Confirm</button></div></dialog>`;}
export function bindEventsCalendar(onChange){
 const dialog=document.querySelector('#calendar-dialog');let selected=eventDay;
 const open=()=>dialog.showModal();document.querySelector('#calendar-open').onclick=open;document.querySelector('#calendar-button').onclick=open;
 document.querySelector('#previous-day').onclick=()=>{eventDay=Math.max(1,eventDay-1);onChange();};document.querySelector('#next-day').onclick=()=>{eventDay=Math.min(31,eventDay+1);onChange();};
 dialog.querySelectorAll('[data-calendar-day]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.calendarDay);dialog.querySelectorAll('[data-calendar-day]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});});
 document.querySelector('#calendar-today').onclick=()=>{eventDay=21;rangeStart="00:00";rangeEnd="23:59";dialog.close();onChange();};document.querySelector('#calendar-confirm').onclick=()=>{const from=document.querySelector('#range-start'),to=document.querySelector('#range-end');to.setCustomValidity('');if(!from.reportValidity()||!to.reportValidity())return;if(to.value<from.value){to.setCustomValidity('End time must be after start time.');to.reportValidity();return;}rangeStart=from.value;rangeEnd=to.value;eventDay=selected;dialog.close();onChange();};

}
